${dataScope}

mapper.select:
SELECT st.tenant_name AS "tenantName", COUNT(1) AS "userTotalNum", SUM(case when dataTable.`STATUS` = '0' then 1 else 0 end) AS "startUserNum", SUM(case when dataTable.`STATUS` = '1' then 1 else 0 end) AS "stopUserNum" FROM sys_user dataTable JOIN (WITH RECURSIVE cte AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM cte WHERE n < 50) SELECT u.user_id, SUBSTRING_INDEX(SUBSTRING_INDEX(u.dept_id, ',', n), ',', -1) AS dept_id FROM sys_user u JOIN cte ON cte.n <= LENGTH(u.dept_id) - LENGTH(REPLACE(u.dept_id, ',', '')) + 1 WHERE u.del_flag = '0') ud ON dataTable.user_id = ud.user_id LEFT JOIN sys_dept sd ON ud.dept_id = sd.dept_id and sd.del_flag = '0' LEFT JOIN sys_tenant_info st ON dataTable.tenant_id = st.tenant_id LEFT JOIN sys_industry_conf ic ON ic.industry_code = sd.INDUSTRY_CODE AND ic.delete_flag = 0
and ic.accept_node =#{localNode}
WHERE dataTable.del_flag = '0' AND dataTable.USER_TYPE = '2' ${dataScope}

SELECT dataTable.USER_ID AS 'userId' FROM sys_user dataTable JOIN (WITH RECURSIVE cte AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM cte WHERE n < 50) SELECT u.user_id, SUBSTRING_INDEX(SUBSTRING_INDEX(u.dept_id, ',', n), ',', -1) AS dept_id FROM sys_user u JOIN cte ON cte.n <= LENGTH(u.dept_id) - LENGTH(REPLACE(u.dept_id, ',', '')) + 1 WHERE u.del_flag = '0') ud ON dataTable.user_id = ud.user_id LEFT JOIN sys_dept sd ON ud.dept_id = sd.dept_id and sd.del_flag = '0'
LEFT JOIN sys_tenant_info st ON dataTable.tenant_id = st.tenant_id LEFT JOIN sys_industry_conf ic ON ic.industry_code = sd.INDUSTRY_CODE AND ic.delete_flag = 0
and ic.accept_node =#{localNode}
WHERE dataTable.del_flag = '0' AND dataTable.USER_TYPE = '2' ${dataScope}
